<script setup>import{onMounted,ref}from'vue';import{studentApi,formatTime}from'../../api/student';const rows=ref([]),error=ref(''),loading=ref(true);onMounted(async()=>{try{rows.value=(await studentApi.results()).data}catch(e){error.value=e.message}finally{loading.value=false}})</script><template><header class="page-heading"><div><h1>我的成绩</h1><p class="muted">这里只展示已经统一公布的正式成绩。</p></div></header><p v-if="error" class="error-message">{{error}}</p><p v-if="loading" class="empty-state">正在加载成绩…</p><p v-else-if="!rows.length" class="empty-state">暂无已发布成绩。</p><div v-else class="course-grid"><article v-for="r in rows" :key="r.submissionId" class="surface result-card"><p class="result-published-at">{{formatTime(r.publishedAt)}} 公布</p><h3>{{r.examTitle}}</h3><p>{{r.courseName}}</p><strong class="score">{{r.totalScore}} / {{r.maxScore}}</strong><RouterLink class="primary result-action" :to="'/student/results/'+r.submissionId">查看成绩</RouterLink></article></div></template>
